def _load_datasets(task, splits=None, transforms=None, normalize=False):
    if splits is None: splits = task['split_names']
    if isinstance(splits, str): splits = [splits]
    if transforms is None: transforms = [[] for _ in range(len(splits))]
    # Simplified dataset loading without torchvision.transforms
    datasets = []
    for split in splits:
        split_idx = task['split_names'].index(split)
        split_path = task['data_path'][split_idx]
        x, y = torch.load(split_path)
        # Assuming MyTensorDataset is a simple TensorDataset for demonstration
        datasets.append(torch.utils.data.TensorDataset(x, y))
    return datasets

def train(model, train_loader, eval_loaders, optimizer, loss_fn, n_it_max, patience, split_names, select_metric='Val accuracy_0', select_mode='max', viz=None, device='cpu', lr_scheduler=None, name=None, log_steps=None, log_epoch=False, _run=None, prepare_batch=None, single_pass=False, n_ep_max=None):
    # This is a simplified stand-in for the actual train function, showing key interaction points
    # In a real scenario, the full ignite-based train function would be included or imported.
    logger.info(f"Simulating train for {name} with max_epochs={n_ep_max} max_iters={n_it_max}")
    best = {'value': float('inf') if select_mode == 'min' else -1, 'iter': -1, 'state_dict': model.state_dict()}
    all_metrics = defaultdict(dict)
    current_iteration = 0
    current_epoch = 0

    if n_ep_max is None and n_it_max is not None: max_epochs = int(n_it_max / len(train_loader)) + 1
    elif n_ep_max is not None: max_epochs = n_ep_max
    else: max_epochs = 1 # Default to 1 if no max specified, or single_pass

    for epoch in range(max_epochs):
        current_epoch = epoch
        for batch_idx, (inputs, targets) in enumerate(train_loader):
            current_iteration += 1
            optimizer.zero_grad()
            # Simplified: assuming model.forward takes inputs directly
            outputs = model(inputs)
            loss = loss_fn(outputs, targets)
            if isinstance(loss, tuple): loss, _ = loss # For SSNWrapper loss
            loss.mean().backward()
            optimizer.step()

            if log_steps and current_iteration in log_steps or (log_epoch and batch_idx == len(train_loader) - 1):
                val_accuracy = 0.5 + 0.5 * np.random.rand() # Simulate some accuracy
                val_loss = loss.mean().item()
                all_metrics['Val accuracy_0'][current_iteration] = val_accuracy
                all_metrics['Val nll'][current_iteration] = val_loss
                all_metrics['training_iteration'][current_iteration] = current_iteration

                if (select_mode == 'max' and val_accuracy > best['value']) or (select_mode == 'min' and val_loss < best['value']):
                    best['value'] = val_accuracy if select_mode == 'max' else val_loss
                    best['iter'] = current_iteration
                    best['state_dict'] = copy.deepcopy(model.state_dict())
            if n_it_max is not None and current_iteration >= n_it_max: break
        if n_it_max is not None and current_iteration >= n_it_max: break
    return current_iteration, all_metrics, best

# From src/models/utils.py
def flatten(x):
    x = x.contiguous()
    n_features = reduce(operator.mul, x.size()[1:])
    return x.view(x.size(0), n_features)

def execute_step(step_calls, use_processes, max_workers=None, ctx=None):
    if not use_processes or len(step_calls) < 2: return [f() for f in step_calls]
    with ProcessPoolExecutor(max_workers, ctx) as executor:
        training_futures = [executor.submit(f) for f in step_calls]
        return [future.result() for future in training_futures]

def _get_used_nodes(graph, candidate_nodes, input, output):
    if input not in candidate_nodes: return set()
    candidate_graph = graph.subgraph(candidate_nodes)
    used_nodes = set()
    for path in nx.all_simple_paths(candidate_graph, input, output):
        used_nodes.update(path)
    return used_nodes

def graph_arch_details(graph):
    detail = {}
    for node in nx.topological_sort(graph):
        node_props = graph.nodes[node]
        mod = node_props['module']
        # Simplified count_params for demonstration
        # n_params = count_params(mod)['trainable'] if hasattr(mod, 'parameters') else 0
        n_params = sum(p.numel() for p in mod.parameters() if p.requires_grad) if hasattr(mod, 'parameters') else 0
        if n_params != 0: detail[len(detail)] = n_params
    return detail

def is_dummy_block(block):
    if isinstance(block, DummyBlock): return True
    if isinstance(block, Add_Block) and not block.activation: return True
    if isinstance(block, nn_torch.Sequential): return all(is_dummy_block(b) for b in block)
    return False

def count_params(model):
    n_params = 0
    n_trainable_params = 0
    for p in model.parameters():
        n_params += p.numel()
        if p.requires_grad: n_trainable_params += p.numel()
    return {'total': n_params, 'trainable': n_trainable_params}

def get_conv_out_size(in_size, kernel_size, padding, stride):
    return [(d + 2*padding - (kernel_size-1) - 1) // stride + 1 for d in in_size]

