# From src/models/change_layer_llmodel.py
class Flatten(nn_torch.Module):
    def forward(self, x):
        return flatten(x)

def _conv_block(in_dim, out_dim, k, stride, pad, dropout_p, pool, pool_k, is_last):
    assert len(in_dim) == 3
    layers = [nn_torch.Conv2d(in_dim[0], out_dim[0], k, stride, pad)]

    if not is_last:
        layers.append(nn_torch.ReLU())
        layers.append(nn_torch.Dropout(dropout_p))

    if pool is not None:
        assert pool == 'maxpool', 'Only Maxpool supported for now'
        layers.append(nn_torch.MaxPool2d(pool_k))
    return layers

def _lin_block(in_dim, out_dim, dropout_p, is_last):
    layers = []
    if not isinstance(in_dim, int):
        in_dim = in_dim[0] * in_dim[1] * in_dim[2]
        layers.append(Flatten())

    layers.append(nn_torch.Linear(in_dim, out_dim))

    if not is_last:
        layers += [nn_torch.ReLU(),
                   nn_torch.Dropout(dropout_p)]

    return layers

def get_block(in_dim, out_dim, dropout_p, k, stride, pad, pool, pool_k, norm_layer, is_first, is_last, residual, block_depth):
    if residual:
        if isinstance(in_dim, (list, tuple)):
            assert len(in_dim) == 3
        layers = _make_layer(BasicBlock, in_dim, out_dim, block_depth, stride, pool, pool_k, norm_layer=norm_layer, is_first=is_first, is_last=is_last)
    elif isinstance(out_dim, int) or len(out_dim) == 1:
        layers = _lin_block(in_dim, out_dim, dropout_p, is_last)
    elif len(out_dim) == 3:
        layers = _conv_block(in_dim, out_dim, k, stride, pad, dropout_p, pool, pool_k, is_last)
    else:
        raise ValueError('Don\'t know which kind of layer to use for input size {} and output size {}.'.format(in_dim, out_dim))

    return nn_torch.Sequential(*layers)

class FrozenSequential(nn_torch.Sequential):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.frozen_modules_idx = []
        self.shared_modules_idx = []

    def requires_grad(self):
        return any(map(lambda t: t.requires_grad, self.parameters()))

    def forward(self, *args, **kwargs):
        for i in self.frozen_modules_idx:
            self[i].eval()
        return super().forward(*args, **kwargs)

    def feats_forward(self, input):
        for i in self.frozen_modules_idx:
            self[i].eval()

        feats = self[:-1](input)
        return feats, self[-1](feats)

    def shared_named_parameters(self, *args, **kwargs):
        filtered_modules = [(i, mod) for i, mod in enumerate(self) if i in self.shared_modules_idx]
        fil_p = [(f'{i}.'+p[0], p[1]) for i, mod in filtered_modules for p in mod.named_parameters()]
        return fil_p

    def arch_repr(self):
        detail = {}
        for block in self:
            detail[len(detail)] = count_params(block)['trainable']
        return detail

