class LifelongLearningModel(nn_torch.Module, abc.ABC):
    def __init__(self, grid_params, ray_resources, *args, **kwargs):
        super(LifelongLearningModel, self).__init__(*args, **kwargs)
        self.models = nn_torch.ModuleList([])
        self.grid_params = grid_params
        self.ray_resources = ray_resources
        self.optim_func = None # placeholder for optim_func assigned by init_optimizer

    def get_model(self, task_id, **task_infos):
        if task_id >= len(self.models):
            assert 'x_dim' in task_infos and 'n_classes' in task_infos
            assert task_id == len(self.models)
            # In MNTDP, the actual model construction (SPNN/ExhaustiveSearch) happens inside _new_model
            # then it's wrapped by this get_model to be appended to self.models
            model_instance = self._new_model(task_id=task_id, **task_infos)
            self.models.append(model_instance)
        return self.models[task_id]

    @abc.abstractmethod
    def _new_model(self, **kwargs):
        raise NotImplementedError

    def n_params(self, t_id):
        all_params = set()
        for i in range(t_id+1):
            model = self.get_model(i)
            all_params.update(model.parameters())
            all_params.update(model.buffers())
        return sum(map(torch.numel, all_params))

    def new_params(self, t_id):
        return self.n_params(t_id) - self.n_params(t_id-1)

    def finish_task(self, dataset, task_id, viz=None, path=None):
        return {}

    def set_h_params(self, **kwargs):
        for k, v in kwargs.items():
            setattr(self, k, v)

# From src/models/modular_model.py
class ModularModel(nn_torch.Module, abc.ABC):
    def __init__(self, n_hidden, n_convs, hidden_size, dropout_p, channel_scaling, base_model=get_block_model, *args, **kwargs):
        super().__init__(*args, **kwargs)
        assert isinstance(hidden_size, list)
        if n_hidden is not None:
            assert len(hidden_size) == 1
            hidden_size = hidden_size * n_hidden
        else:
            assert n_hidden is None
        self.hidden_size = hidden_size
        self.channel_scaling = channel_scaling

        if isinstance(dropout_p, int):
            dropout_p = [dropout_p] * len(self.hidden_size)
        self._dropout_p = dropout_p

        self.n_convs = n_convs
        self.base_model_func = partial(base_model, dropout_p=dropout_p, n_convs=self.n_convs)

    def get_k(self, layer):
        if layer >= self.n_convs: return None
        elif isinstance(self._k, (tuple, list)): return self._k[layer]
        else: return self._k

    def get_stride(self, layer):
        if layer >= self.n_convs: return None
        elif isinstance(self._stride, (tuple, list)): return self._stride[layer]
        else: return self._stride

    def get_pad(self, layer):
        if layer >= self.n_convs: return None
        elif isinstance(self._pad, (tuple, list)): return self._pad[layer]
        else: return self._pad

    def get_dropout_p(self, layer):
        if isinstance(self._dropout_p, (tuple, list)): return self._dropout_p[layer]
        else: return self._dropout_p

    def get_pool_k(self, layer):
        if layer >= self.n_convs: return None
        if isinstance(self._pool_k, (tuple, list)): return self._pool_k[layer]
        else: return self._pool_k

    def get_sizes(self, x_dim, n_classes):
        if len(x_dim) == 1:
            x_dim = x_dim[0]
            assert self.n_convs == 0, 'Can\'t use convs on 1D inputs.'
        assert len(n_classes) == 1, 'Only supports single output'
        n_classes = n_classes[0]

        model_dims = [x_dim, *self.hidden_size, n_classes]

        for i in range(self.n_convs):
            img_size = model_dims[i][1:]
            k = self.get_k(i)
            pad = self.get_pad(i)
            stride = self.get_stride(i)
            out_size = get_conv_out_size(img_size, k, pad, stride)
            pool_k = self.get_pool_k(i)
            if pool_k is not None:
                out_size = get_conv_out_size(out_size, pool_k, 0, pool_k)
            model_dims[i + 1] = [model_dims[i + 1], *out_size]
        return model_dims

    def get_res_sizes(self, x_dim, n_classes):
        if len(x_dim) == 1:
            x_dim = x_dim[0]
            assert self.n_convs == 0, 'Can\'t use convs on 1D inputs.'
        assert len(n_classes) == 1, 'Only supports single output'
        n_classes = n_classes[0]

        model_dims = [x_dim, *self._res_hidden_size, n_classes]

        for i in range(self.n_res_blocks + 1):
            img_size = model_dims[i][1:]
            k = self._k
            pad = self._pad
            stride = self._res_stride[i]
            out_size = get_conv_out_size(img_size, k, pad, stride)
            pool_k = self._res_pool_k[i]
            if pool_k is not None:
                out_size = get_conv_out_size(out_size, pool_k, 0, pool_k)
            model_dims[i + 1] = [model_dims[i + 1], *out_size]
        return np.array(model_dims)

# From src/models/samplers/arch_sampler.py
class ArchSampler(nn_torch.Module):
    def __init__(self, distrib_dim, all_same, deter_eval, var_names=None, *args, **kwargs):
        super().__init__()
        self.distrib_dim = distrib_dim
        self.all_same = all_same
        self.deter_eval = deter_eval
        self.frozen = False
        self.log_probas = None
        self.distrib_entropies = None
        self._seq_probas = None

        if var_names is not None:
            assert len(var_names) == self.distrib_dim
        self.var_names = var_names

    def freeze(self):
        self.frozen = True

    def start_new_sequence(self):
        self.log_probas = []
        self.distrib_entropies = []
        self._seq_probas = []

    def nodes_to_prune(self, treshold):
        nodes = []
        for node, weight in zip(self.var_names, self().squeeze().unbind()):
            if weight < treshold:
                nodes.append(node)
        return nodes

    def sample_archs(self, batch_size, probas):
        self._check_probas(probas, self.all_same)

        if probas.size(0) != batch_size:
            if probas.size(0) != 1:
                raise ValueError('Sampling probabilities dimensions {} doesn\'t match with batch size {}.'.format(probas.size(), batch_size))
            if not self.all_same:
                probas = probas.expand(batch_size, -1)

        distrib = torch.distributions.Bernoulli(probas)
        if not self.training and self.deter_eval:
            samplings = (probas > 0.5).float()
        else:
            samplings = distrib.sample()

        if self.all_same:
            samplings = samplings.expand(batch_size, -1)

        self._seq_probas.append(probas)
        self.distrib_entropies.append(distrib.entropy())
        self.log_probas.append(distrib.log_prob(samplings))
        return samplings

    def _check_probas(self, probas, all_same):
        if probas.dim() != 2 or all_same and probas.size(0) != 1:
            raise ValueError('probas params has wrong dimension: {} (all_same={})'.format(probas.size(), all_same))

        if probas.size(-1) != self.distrib_dim:
            raise ValueError('Should have exactly as many probas as the number of stochastic nodes({}), got {} instead.'.format(self.distrib_dim, probas.size(-1)))

    @property
    def last_arch_probas(self):
        return self.probas

    @property
    def last_sequence_probas(self):
        return torch.stack(self._seq_probas)

# From src/models/samplers/softmax_sampler.py
class SoftmaxArchGenerator(ArchSampler):
    def __init__(self, groups, graph, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.groups = groups
        id_gen = defaultdict()
        id_gen.default_factory = id_gen.__len__
        group_ids = torch.tensor([id_gen[grp] for grp in groups])
        self.group_ids_index = dict(id_gen.items())

        self.distrib_groups = group_ids
        self.graph = graph

        self.group_ids = self.distrib_groups.unique()
        self.group_masks = [self.distrib_groups.eq(id) for id in self.group_ids]
        self.group_var_names = [[] for _ in range(self.group_ids.numel())]
        for grp, var in zip(self.distrib_groups.unbind(), self.var_names):
            self.group_var_names[grp.item()].append(var)
        self.group_sizes = [mask.sum().item() for mask in self.group_masks]

        self.params = [nn_torch.Parameter(torch.zeros(size)) for size in self.group_sizes]
        self.params = nn_torch.ParameterList(self.params)

    def forward(self, z=None):
        return self.get_distrib()

    def entropy(self):
        entropies = [Categorical(p.softmax(0)).entropy() for p in self.params]
        return torch.stack(entropies).mean() if entropies else torch.Tensor()

    def remove_var(self, name):
        assert self.var_names
        self.distrib_dim -= 1
        remove_idx = self.var_names.index(name)
        grp_idx = self.distrib_groups[remove_idx]
        idx_in_group = self.group_masks[grp_idx][:remove_idx].sum().item()
        self.var_names.remove(name)

        self.group_var_names[grp_idx].remove(name)

        all_idx_mask = torch.ones_like(self.distrib_groups).bool()
        all_idx_mask[remove_idx] = 0
        self.distrib_groups = self.distrib_groups[all_idx_mask]
        self.group_masks = [m[all_idx_mask] for m in self.group_masks]

        param = self.params[grp_idx]
        group_idx_mask = torch.ones_like(param).bool()
        group_idx_mask[idx_in_group] = 0
        self.params[grp_idx] = nn_torch.Parameter(param[group_idx_mask])

        self.group_sizes[grp_idx] -= 1

    def get_distrib(self):
        device = self.params[0].device if self.params else 'cpu'
        distrib = torch.zeros(self.distrib_dim).to(device)
        for p, mask in zip(self.params, self.group_masks):
            mask = mask.to(device)
            distrib[mask] = p.softmax(0)
        return distrib.unsqueeze(0)

    def is_deterministic(self):
        distrib = self.get_distrib()
        return torch.equal(distrib, distrib**2)

    def sample_archs(self, batch_size, probas, force_deterministic=False):
        deterministic = not self.training and self.deter_eval or force_deterministic
        self._check_probas(probas, self.all_same)

        if probas.size(0) != batch_size:
            if probas.size(0) != 1:
                raise ValueError('Sampling probabilities dimensions {} doesn\'t match with batch size {}.'.format(probas.size(), batch_size))

        samplings = torch.zeros_like(probas)
        entropy = torch.zeros(0).to(samplings.device)
        log_probs = torch.zeros(0).to(samplings.device)
        if not self.all_same:
            samplings = samplings.repeat(batch_size, 1)
            entropy = entropy.repeat(batch_size, 1)
            log_probs = log_probs.repeat(batch_size, 1)

        for mask in self.group_masks:
            if not any(mask): continue
            masked_probas = probas[mask.unsqueeze(0)].unsqueeze(0)
            if not self.all_same:
                masked_probas = masked_probas.repeat(batch_size, 1)
            distrib = Categorical(masked_probas)

            if deterministic:
                index = masked_probas.argmax(1)
            else:
                index = distrib.sample()

            new_sampling = f.one_hot(index, masked_probas.size(-1)).float()

            expanded_mask = mask.expand_as(samplings)
            samplings[expanded_mask] = new_sampling.flatten()

            entropy = torch.cat((entropy, distrib.entropy().unsqueeze(1)), 1)
            log_probs = torch.cat((log_probs, distrib.log_prob(index).unsqueeze(1)), 1)

        if self.all_same:
            samplings = samplings.expand(batch_size, -1)

        self.distrib_entropies.append(entropy)
        self.log_probas.append(log_probs)
        return samplings

    def nodes_to_prune(self, *args, **kwargs):
        distrib = self()
        arch = self.sample_archs(1, distrib, True)
        nodes = self.var_names.copy()

        for var, sampled in zip(self.var_names, arch.unbind(-1)):
            if sampled[0]:
                nodes.remove(var)
        return nodes

# From src/models/samplers/conditional_softmax_sampler.py
class CondiSoftmaxArchGenerator(SoftmaxArchGenerator):
    def sample_archs(self, batch_size, probas, force_deterministic=False):
        torch.autograd.set_detect_anomaly(True)
        deterministic = not self.training and self.deter_eval or force_deterministic
        self._check_probas(probas, self.all_same)

        if probas.size(0) != batch_size:
            if probas.size(0) != 1:
                raise ValueError('Sampling probabilities dimensions {} doesn\'t match with batch size {}.'.format(probas.size(), batch_size))

        samplings = torch.zeros_like(probas)
        entropies = []
        log_probs = []
        if not self.all_same:
            samplings = samplings.repeat(batch_size, 1)
        order = list(nx.topological_sort(self.graph))

        has_input_mat = torch.zeros(len(order), batch_size).bool().to(probas.device)
        has_input = {n: t for n, t in zip(order, has_input_mat.unbind(0))}
        has_input_mat[0] = True

        for node in order:
            node_input = has_input[node]
            if not node_input.any(): continue

            grp_id = self.group_ids_index.get(node)
            if grp_id is None:
                next_nodes = self.graph.successors(node)
                for neighbor in next_nodes:
                    has_input[neighbor] = has_input[neighbor] | node_input
            else:
                mask = self.group_masks[grp_id]
                masked_probas = probas[mask.unsqueeze(0)].unsqueeze(0)
                if not self.all_same:
                    masked_probas = masked_probas.repeat(node_input.sum(), 1)
                distrib = Categorical(masked_probas)

                assert masked_probas.dim() == 2
                if deterministic or masked_probas.size(1) == 1:
                    index = masked_probas.argmax(1)
                else:
                    index = distrib.sample()

                samplable_nodes = self.group_var_names[grp_id]
                assert masked_probas.size(1) == len(samplable_nodes)
                for idx, next_node in enumerate(samplable_nodes):
                    has_input[next_node][node_input] = (has_input[next_node][node_input] | (index == idx))
                    next_succ = list(self.graph.successors(next_node))
                    assert len(next_succ) == 1

                new_sampling = f.one_hot(index, masked_probas.size(-1)).float()

                expanded_mask = mask.repeat(samplings.size(0), 1)
                expanded_mask[~node_input] = False
                samplings[expanded_mask] = new_sampling.flatten()

                ent = torch.zeros(samplings.size(0)).to(probas.device)
                ent[node_input] = distrib.entropy()
                entropies.append(ent)

                lp = torch.zeros(samplings.size(0)).to(probas.device)
                lp = lp.masked_scatter(node_input.clone(), distrib.log_prob(index))
                log_probs.append(lp)

        if self.all_same:
            samplings = samplings.expand(batch_size, -1)

        if entropies:
            self.distrib_entropies.append(torch.stack(entropies, 1))
        if log_probs:
            self.log_probas.append(torch.stack(log_probs, 1))
        return samplings

# From src/models/SPNN.py (inherits from a supernets.networks.StochasticSuperNetwork which is not provided, so I'll make it a standalone) 
class StochasticSuperNetwork(nn_torch.Module):
    def __init__(self):
        super().__init__()
        self.stochastic_node_ids = {}
        self.n_sampling_params = 0
        self.graph = None
        self.in_nodes = []
        self.out_nodes = []
        self.traversal_order = []
        self.samplings = None # Added for SSNWrapper to set

    def register_stochastic_node(self, node):
        self.stochastic_node_ids[node] = self.n_sampling_params
        self.n_sampling_params += 1

    def set_graph(self, graph, in_nodes, out_nodes):
        self.graph = graph
        self.in_nodes = in_nodes
        self.out_nodes = out_nodes
        self.traversal_order = list(nx.topological_sort(graph))

    def forward(self, inputs):
        if not self.graph: raise RuntimeError("Graph not set")
        assert len(self.in_nodes) == 1 and len(self.out_nodes) == 1, "Only single input/output for now"
        in_node = self.in_nodes[0]
        out_node = self.out_nodes[0]

        node_outputs = {}
        node_outputs[in_node] = inputs

        for node in self.traversal_order:
            if node == in_node: continue

            current_node_inputs = []
            for predecessor in self.graph.predecessors(node):
                if predecessor in node_outputs:
                    if self.stochastic_node_ids.get(node) is not None:
                        idx = self.stochastic_node_ids[node]
                        if self.samplings is not None and self.samplings[..., idx].any():
                            current_node_inputs.append(node_outputs[predecessor])
                    else:
                        current_node_inputs.append(node_outputs[predecessor])

            if not current_node_inputs: continue

            if len(current_node_inputs) > 1 and isinstance(self.graph.nodes[node]['module'], Add_Block):
                node_input = sum(current_node_inputs)
            elif len(current_node_inputs) > 1:
                node_input = torch.cat(current_node_inputs, dim=1)
            else:
                node_input = current_node_inputs[0]

            module = self.graph.nodes[node]['module']
            if is_dummy_block(module):
                node_outputs[node] = node_input
            else:
                node_outputs[node] = module(node_input)

        return [node_outputs[out_node]]


class SPNN(StochasticSuperNetwork):
    def __init__(self, graph, tunable_modules, frozen_modules, stochastic_nodes, in_node, out_node, single_stage):
        super(SPNN, self).__init__()
        self.tunable_modules = nn_torch.ModuleList(tunable_modules)
        self.tunable_modules.requires_grad_(True)
        self.frozen_modules = nn_torch.ModuleList(frozen_modules)
        self.frozen_modules.requires_grad_(False)
        self.graph = graph

        self.single_stage = single_stage
        self.block_inits = {}
        nodes_to_raise = []
        for node in graph.nodes:
            mod = graph.nodes[node]['module']
            if not (self.single_stage or mod in frozen_modules):
                self.block_inits[node] = copy.deepcopy(mod.state_dict())
            if node in stochastic_nodes:
                if node not in graph:
                    nodes_to_raise.append(node)
                self.register_stochastic_node(node)

        if nodes_to_raise:
            raise ValueError('Nodes to register not in graph {}'.format(nodes_to_raise))

        self.set_graph(self.graph, [in_node], [out_node])

    def forward(self, inputs):
        return super(SPNN, self).forward(inputs)[0]

    def train(self, mode=True):
        super().train(mode)
        self.frozen_modules.train(False)
        return self

    def get_pruned_model(self, weights):
        assert weights.ndim == 1
        assert torch.equal(weights, weights ** 2)
        candidates = set()
        for node in self.graph.nodes:
            if node not in self.stochastic_node_ids:
                candidates.add(node)
            else:
                idx = self.stochastic_node_ids[node]
                if weights[idx] == 1:
                    candidates.add(node)
        used_nodes = _get_used_nodes(self.graph, candidates, self.in_nodes[0], self.out_nodes[0])

        new_model = FrozenSequential()
        last = None
        i = 0
        for node in self.traversal_order:
            if node not in used_nodes: continue
            assert node == self.in_nodes[0] or node in self.graph.successors(last)
            nn_module = self.graph.nodes[node]['module']
            last = node
            if is_dummy_block(nn_module): continue
            new_model.add_module(str(i), nn_module)
            if nn_module in self.frozen_modules: new_model.frozen_modules_idx.append(i)
            i += 1
        return new_model

# From src/models/ExhaustiveSearch.py
class ExhaustiveSearch(nn_torch.Module):
    def __init__(self, graph, tunable_modules, frozen_modules, stochastic_nodes, in_node, out_node, max_new_blocks):
        super(ExhaustiveSearch, self).__init__()
        self.tunable_modules = nn_torch.ModuleList(tunable_modules)
        self.tunable_modules.requires_grad_(True)
        self.frozen_modules = nn_torch.ModuleList(frozen_modules)
        self.frozen_modules.requires_grad_(False)
        self.stochastic_nodes = stochastic_nodes
        self.graph = graph
        self.in_node = in_node
        self.out_node = out_node
        self.models = nn_torch.ModuleList()
        self.models_idx = {}
        self.res = {}

        self.max_new_blocks = max_new_blocks
        self.n_out = 1 # Placeholder, will be set by MNTDP

    def init_models(self):
        archs = list(nx.all_simple_paths(self.graph, self.in_node, self.out_node))
        for path in archs:
            new_model = FrozenSequential()
            last = None
            i = 0
            n_new_blocks = 0
            for node in path:
                assert node == self.in_node or node in self.graph.successors(last)
                nn_module = self.graph.nodes[node]['module']
                last = node
                if is_dummy_block(nn_module): continue
                new_model.add_module(str(i), nn_module)
                if nn_module in self.frozen_modules: new_model.frozen_modules_idx.append(i)
                else: n_new_blocks += 1
                i += 1

            if n_new_blocks > self.max_new_blocks and len(archs) > 1: continue
            new_model.n_out = self.n_out
            self.models_idx[tuple(path)] = len(self.models_idx)
            self.models.append(new_model)

    def get_weights(self):
        weights = torch.tensor([1. if n in self._selected_path() else 0. for n in self.stochastic_nodes])
        return weights

    def _selected_path(self):
        assert self.res
        all_res = map(lambda x: (x[1][2]['value'], x[0]), self.res.items())
        return max(all_res, key=itemgetter(0))[1]

    def get_stoch_nodes(self):
        return self.stochastic_nodes

    def get_graph(self):
        return self.graph

    def nodes_to_prune(self, *args):
        return [n for n in self.stochastic_nodes if n not in self._selected_path()]

    def train_func(self, datasets_p, b_sizes, optim_fact, *args, **kwargs):
        if not self.models: self.init_models()
        calls = []
        for path, idx in self.models_idx.items():
            model = self.models[idx]
            calls.append(partial(wrap, model=model, idx=idx, optim_fact=optim_fact, datasets_p=datasets_p, b_sizes=b_sizes, *args, **kwargs))
        ctx = torch.multiprocessing.get_context('spawn')
        all_res = execute_step(calls, True, 4, ctx=ctx)
        for path, res in zip(self.models_idx.keys(), all_res):
            self.res[path] = res
        all_res = list(map(lambda x: (x[1][2]['value'], x[0]), self.res.items()))
        best_path = max(all_res, key=itemgetter(0))[1]
        _, best_metrics, best_chkpt = self.res[best_path]
        total_t = 0
        cum_best_iter = 0

        splits = ['Trainer', 'Train', 'Val', 'Test']
        metrics = ['accuracy_0']

        all_xs = []
        best_accs = list(self.res[best_path][1]['Val accuracy_0'].values())

        for i, (path, (t, logs, best)) in enumerate(self.res.items()):
            total_t += t
            cum_best_iter += best['iter']
            for m in metrics:
                for s in splits:
                    best_metrics[f'{s} {i} {m}_all'] = logs[f'{s} {m}']
                    if s == 'Val':
                        all_xs.append(list(logs[f'{s} {m}'].keys()))
        max_len = max(map(len, all_xs))
        # simplified zip for scaling, original uses itertools.zip_longest
        scaled_xs = [sum(steps) for steps in zip(*all_xs)] if all_xs else []
        scaled_ys = best_accs # Needs padding if scaled_xs is longer in real implementation
        new_metric = dict(zip(scaled_xs, scaled_ys))
        best_metrics['Val accuracy_0_rescaled'] = new_metric

        self.models[self.models_idx[best_path]].load_state_dict(best_chkpt['state_dict'])
        best_chkpt['cum_best_iter'] = cum_best_iter
        return total_t, best_metrics, best_chkpt

    def forward(self, input):
        if not self.models: self.init_models()
        assert len(self.models) == 1, len(self.models)
        return self.models[0](input)

    def get_frozen_model(self):
        if not self.models: self.init_models()
        assert len(self.models) == 1, len(self.models)
        return self.models[0]

    def get_top_archs(self, n=1):
        res = list(map(lambda x: (x[0], x[1][2]['value']), self.res.items()))
        res = sorted(res, key=itemgetter(1), reverse=True)
        return OrderedDict(res[:n])

    def arch_repr(self):
        return graph_arch_details(self.graph)

def wrap(*args, idx=None, uid=None, optim_fact, datasets_p, b_sizes, **kwargs):
    model = kwargs['model']
    optim = optim_fact(model=model)
    datasets = _load_datasets(**datasets_p)
    train_loader, eval_loaders = get_classic_dataloaders(datasets, b_sizes, 0)
    if hasattr(model, 'train_loader_wrapper'):
        train_loader = model.train_loader_wrapper(train_loader)

    res = train(*args, train_loader=train_loader, eval_loaders=eval_loaders, optimizer=optim, **kwargs)
    return res

